### Python

```python
import sys
sys.setrecursionlimit(1 << 25)   # 实际上本题使用显式栈，无需此设置，保留以防万一

def main():
    input = sys.stdin.readline
    n = int(input())
    a = list(map(int, input().split()))
    # 邻接表
    g = [[] for _ in range(n)]
    for _ in range(n - 1):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        g[u].append(v)
        g[v].append(u)

    visited = [False] * n
    total_path = n * (n - 1) // 2
    same_path = 0          # 所有同能量连通块内部路径总数
    ans = 0

    for i in range(n):
        if not visited[i]:
            val = a[i]
            cnt = 0
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                cnt += 1
                for v in g[u]:
                    if not visited[v] and a[v] == val:
                        visited[v] = True
                        stack.append(v)
            block_path = cnt * (cnt - 1) // 2
            ans += block_path * val
            same_path += block_path

    # 跨能量块路径贡献
    ans += (total_path - same_path) * 15
    print(ans)

if __name__ == "__main__":
    main()
```

