        int n = Integer.parseInt(br.readLine());
        int[] a = new int[n];
        String[] parts = br.readLine().split(" ");
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(parts[i]);
        }

        List<Integer>[] g = new ArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            parts = br.readLine().split(" ");
            int u = Integer.parseInt(parts[0]) - 1;
            int v = Integer.parseInt(parts[1]) - 1;
            g[u].add(v);
            g[v].add(u);
        }

        boolean[] visited = new boolean[n];
        long totalPath = (long) n * (n - 1) / 2;
        long samePath = 0;
        long ans = 0;

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                int val = a[i];
                int cnt = 0;
                Deque<Integer> stack = new ArrayDeque<>();
                stack.push(i);
                visited[i] = true;
                while (!stack.isEmpty()) {
                    int u = stack.pop();
                    cnt++;
                    for (int v : g[u]) {
                        if (!visited[v] && a[v] == val) {
                            visited[v] = true;
                            stack.push(v);
                        }
                    }
                }
                long blockPath = (long) cnt * (cnt - 1) / 2;
                ans += blockPath * val;
                samePath += blockPath;
            }
        }

        ans += (totalPath - samePath) * 15;
        System.out.println(ans);
    }
}
